The analyser parses each module, walks only statements that execute at import time, resolves each import to a project module, and runs Tarjan's strongly-connected-components algorithm on the resulting graph. Components larger than one module are exactly the groups that import each other directly or transitively. Fixing them means breaking an edge: extract a shared module, import the module instead of the name, or defer or `TYPE_CHECKING`-guard the import.

**`importgraph.py`**

```python
from __future__ import annotations

import ast
from collections.abc import Mapping


def _is_type_checking(test: ast.expr) -> bool:
    return (isinstance(test, ast.Name) and test.id == "TYPE_CHECKING") or (
        isinstance(test, ast.Attribute) and test.attr == "TYPE_CHECKING"
    )


def _module_level_imports(body: list[ast.stmt]) -> list[ast.Import | ast.ImportFrom]:
    """Imports that execute at import time: skips function bodies and TYPE_CHECKING blocks."""
    found: list[ast.Import | ast.ImportFrom] = []
    for node in body:
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            found.append(node)
        elif isinstance(node, ast.If):
            if not _is_type_checking(node.test):
                found += _module_level_imports(node.body)
            found += _module_level_imports(node.orelse)
        elif isinstance(node, ast.Try):
            for block in (node.body, node.orelse, node.finalbody, *(h.body for h in node.handlers)):
                found += _module_level_imports(block)
        elif isinstance(node, ast.ClassDef):
            found += _module_level_imports(node.body)
    return found


def _resolve_from(module: str, is_package: bool, level: int, name: str | None) -> str | None:
    if level == 0:
        return name
    parts = module.split(".")
    package = parts if is_package else parts[:-1]
    keep = len(package) - (level - 1)
    if keep <= 0:
        return None  # relative import beyond the top-level package
    base = package[:keep]
    return ".".join(base + ([name] if name else []))


def build_import_graph(sources: Mapping[str, str]) -> dict[str, set[str]]:
    """Map each project module to the project modules it imports at import time."""
    modules = set(sources)
    packages = {m for m in modules if any(o.startswith(m + ".") for o in modules)}
    graph: dict[str, set[str]] = {m: set() for m in modules}
    for module, source in sources.items():
        for node in _module_level_imports(ast.parse(source).body):
            targets: list[str] = []
            if isinstance(node, ast.Import):
                targets = [alias.name for alias in node.names]
            else:
                base = _resolve_from(module, module in packages, node.level, node.module)
                if base is not None:
                    # "from pkg import name": an edge to pkg.name if that is a module, else to pkg
                    targets = [
                        f"{base}.{a.name}" if f"{base}.{a.name}" in modules else base
                        for a in node.names
                    ]
            for target in targets:
                # keep the longest known prefix: "pkg.mod.attr" -> "pkg.mod"
                parts = target.split(".")
                while parts and ".".join(parts) not in modules:
                    parts.pop()
                if parts and ".".join(parts) != module:
                    graph[module].add(".".join(parts))
    return graph


def find_cycles(graph: Mapping[str, set[str]]) -> list[list[str]]:
    """Strongly connected components with more than one module (Tarjan), sorted."""
    index: dict[str, int] = {}
    low: dict[str, int] = {}
    on_stack: set[str] = set()
    stack: list[str] = []
    cycles: list[list[str]] = []
    counter = 0

    def visit(v: str) -> None:
        nonlocal counter
        index[v] = low[v] = counter
        counter += 1
        stack.append(v)
        on_stack.add(v)
        for w in sorted(graph.get(v, ())):
            if w not in index:
                visit(w)
                low[v] = min(low[v], low[w])
            elif w in on_stack:
                low[v] = min(low[v], index[w])
        if low[v] == index[v]:
            component: list[str] = []
            while True:
                w = stack.pop()
                on_stack.discard(w)
                component.append(w)
                if w == v:
                    break
            if len(component) > 1:
                cycles.append(sorted(component))

    for v in sorted(graph):
        if v not in index:
            visit(v)
    return sorted(cycles)
```

**`test_importgraph.py`**

```python
from importgraph import build_import_graph, find_cycles

SOURCES = {
    "gw": "",
    "gw.config": "from gw.providers import NAMES\nSETTINGS = 1",
    "gw.providers": "from gw.config import SETTINGS\nNAMES = ['a']",
    "gw.util": "VALUE = 1",
    "gw.core": "from . import util\nfrom .util import VALUE\nimport json\n",
    "gw.cli": "import gw.core\nfrom gw import config",
}


def test_graph_resolves_absolute_and_relative_imports_and_ignores_external() -> None:
    graph = build_import_graph(SOURCES)
    assert graph["gw.config"] == {"gw.providers"}
    assert graph["gw.providers"] == {"gw.config"}
    assert graph["gw.core"] == {"gw.util"}  # `json` is not a project module
    assert graph["gw.cli"] == {"gw.core", "gw.config"}


def test_cycles_are_reported_as_sorted_components() -> None:
    graph = build_import_graph(SOURCES)
    assert find_cycles(graph) == [["gw.config", "gw.providers"]]


def test_deferred_and_type_checking_imports_do_not_create_edges() -> None:
    sources = {
        "a": "from typing import TYPE_CHECKING\nif TYPE_CHECKING:\n    import b\n",
        "b": "import a\n\ndef f():\n    import a\n",
    }
    graph = build_import_graph(sources)
    assert graph["a"] == set()
    assert graph["b"] == {"a"}
    assert find_cycles(graph) == []


def test_imports_inside_try_and_if_blocks_count() -> None:
    sources = {
        "x": "try:\n    import y\nexcept ImportError:\n    y = None\n",
        "y": "import x\n",
    }
    assert find_cycles(build_import_graph(sources)) == [["x", "y"]]


def test_relative_import_beyond_top_level_is_ignored() -> None:
    sources = {"pkg": "", "pkg.m": "from ..outside import z"}
    assert build_import_graph(sources)["pkg.m"] == set()


def test_package_init_relative_imports() -> None:
    sources = {"pkg": "from . import a", "pkg.a": "import pkg"}
    graph = build_import_graph(sources)
    assert graph["pkg"] == {"pkg.a"}
    assert find_cycles(graph) == [["pkg", "pkg.a"]]


def test_three_module_cycle_and_self_import() -> None:
    sources = {
        "a": "import b",
        "b": "import c",
        "c": "import a\nimport c",
        "d": "import d",
    }
    assert find_cycles(build_import_graph(sources)) == [["a", "b", "c"]]
```

Run the tests with `pytest -q`.
